css:
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 12px;
  padding: 12px;
}

.card {
  padding: 16px 12px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

.featured {
  grid-column: 1 / -1; /* first line to last */
  background: #18181b;
  color: #fafafa;
  border-color: #18181b;
}
